function bkGemVerdict(c,x){
 const p=x.p,g=BK_P[p].gem,L=c.L;let v,why=[];
 if(p=='Rahu'){const okL=[1,2,5,6,9,10].includes(L),badL=[0,7,3,4].includes(L);
  v=okL?'ok':badL?'no':'cond';why.push(okL?'Gomed suits Taurus, Gemini, Virgo, Libra, Capricorn and Aquarius Lagnas (Rahu’s friends rule your chart).':badL?'Aries, Scorpio, Cancer and Leo Lagnas should not wear Gomed (Sun, Moon and Mars are Rahu’s enemies).':'Sagittarius and Pisces Lagnas should avoid Gomed unless essential (Rahu–Jupiter forms Chandal Yoga).');why.push('Wear only on a qualified astrologer’s advice, preferably in the Rahu dasha.');return{v,why}}
 if(p=='Ketu'){const h=c.h.Ketu;v=[2,3,4,5,9,10].includes(h)?'ok':'cond';why.push('Cat’s Eye is for a malefic, weak or combust Ketu; it is favourable if Ketu is in the 2nd, 3rd, 4th, 5th, 9th or 10th house (yours is in the '+pxOrd(h)+'). Better worn in the Ketu major or sub period on expert advice.');return{v,why}}
 const sg=BK_GEMSIGN[L][p],st=sg[0],gen='Book’s general rule for your Lagna: '+sg[1]+'.';
 if(c.dig(p)=='debilitated'){v='no';why.push('The planet is debilitated: the book never prescribes the gem of a debilitated planet.',gen)}
 else if(c.strongDig(p)){v='no';why.push('The planet is exalted or in its own sign and already strong; the book says no gem is needed.',gen)}
 else if(st=='n'||st=='a'){v='no';why.push(gen,st=='n'?'The book says never to wear it for this Lagna.':'The book advises against it for this Lagna.')}
 else if(st=='d'){v='cond';why.push(gen,'Conditional: only in this planet’s own dasha or when really needed.')}
 else{v=(c.combust(p)||x.s&&x.s.band=='Weak'||x.dg=='enemy sign')?'ok':'cond';why.push(gen,v=='ok'?'The planet is weak or combust, so the gem is the book’s remedy to raise its power.':'The gem is favourable for this Lagna but the planet is not weak; wear only if the astrologer finds a need.')}
 return{v,why}}
